    }, {
      "type": "text",
      "value": "<p>Unexpired term candidates for Wyckoff</p>"
    }, {
      "type": "text",
      "value": "<ul>
<li>Roger J. Lane* - Republicans for Wyckoff - 270 votes received </li>



<li>Christopher G. Joachim - Republicans for Responsible Government - 221 votes received </li>
</ul>"
    }]
  }
}

